  (* [comment removed for export] *)
  Lemma rf_umap : forall msF1 mo1, nf < n -> mu < rf_total c nf au ->
    rf2_at L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu fl msF1 mo1 ->
    (forall msF' mo', rf3_at L S Zr mo ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo c CA P R sb ARI rbeg FAB TH TSD CTX nf mfa au mu (mu + 262144) fl msF' mo' ->
                      sreach asegs Q (mkCfg msF' mo')) ->
    sreach asegs Q (mkCfg msF1 mo1).
  (* [Proof using] keeps this lemma's closed statement (its section variables) equal to the one its
     former recorded body had, which [refill_sreach]'s recorded body (AS_Refill4.v) applies positionally. *)
  Proof using HCEIL L S Zr mo Q ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m lo sb c CA TH CTX TSD nf mfa au mu fl LO HI SPT SPA HC CAE
             SBR SBA TPR RNG THA PLC NFR AUR MUA FLL LENF ATOP RESF PRIM NW NWA NOV ZRP ZRSH LSH SVIS BUD.
    intros msF1 mo1 NF TOT A1 K. prepR.
    clear MI ST ENV PC1 PCJ FAM QST TST RI RIJ EXH RST FARR FAJ USJ VISE OK.
    destruct A1 as (u0 & u1 & u2 & u5 & u6 & u7 & x7 & x8 & x9 & s10' & s11' & u3 & u4 & u5' & u6' & q0' & q1' & q2' & q3' & j8 & j24 & m1
                    & OK1 & VIS1 & SBM1 & MU & WM & MI1 & ENV1 & ST1 & FRP & FRG & FRR & PC0 & PCJ & FAMv & QST & TST & RI & RIJ & EXH & RST & FARR & FAJ & USJ).
    rewrite (proj2 (Z.ltb_lt mu (rf_total c nf au))) in VIS1 by exact TOT.
    pose proof (rf_batch_small c HC) as [BSM _]. fold n csz in BSM.
    assert (TOTB : au + csz <= rf_total c nf au <= au + 65536) by (unfold rf_total, rf_k; fold n csz; clear - BSM NF NR CSZ NFR; try acb; nia).
    assert (MS256 : pop_ms (rf_total c nf au) mu = 262144)
      by (unfold pop_ms, round_up, kUserMapSize; clear - TOTB TOT AUR CSZ; try acb; Z.div_mod_to_equations; lia).
    (* [comment removed for export] *)
    pose proof (re_isb _ _ _ _ _ _ _ ENV1) as ISB. apply (proj1 (rw_cells_app asegs _ _ [_;_] _)) in ISB. destruct ISB as [ISB _].
    pose proof (re_pmh _ _ _ _ _ _ _ ENV1) as PMH. pose proof (re_senv _ _ _ _ _ _ _ ENV1) as SE.
    pose proof (se_got _ _ _ _ _ SE) as GOT. pose proof (se_psc _ _ _ _ _ SE) as PSC. pose proof (se_dpm _ _ _ _ _ SE) as DPM. clear SE.
    replace (Z_to_bv 64 (bv_unsigned sp + -224)) with (Z_to_bv 64 (bv_unsigned (Z_to_bv 64 (bv_unsigned sp + -160)) + -64)) in VIS1
      by (f_equal; rewrite unsigned_lit by lia; lia).
    eapply (evt_sreach_lazy_at asegs L S Zr _ msF1 _ mo1 Q OK1 VIS1).
    { getAL CAR ARIR SBR4 RR RBG.
      eapply (pop_map_seg1 _ (Z_to_bv 64 (bv_unsigned sp + -160)) gp tp _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ s10' s11' _ _ _ _
                F fc m1 lo c R (CA + 2560) sb (n - nf) nf mfa au mu);
        try eassumption; rewrite ?unsigned_lit by (first [clear - BND HI; lia | lia]).
      all: try eassumption. all: try reflexivity. all: try (clear - RR; try acb; (first [clear; solve [repeat split; exact I] | (first [clear; solve [repeat split; exact I] | clear; tauto | (lazymatch goal with H1 : _ |- _ => revert H1; clear; tauto end) | tauto])])).
      (* [comment removed for export] *)
      all: try (lazymatch goal with |- AHI_LO <= sb /\ _ => idtac end;
                unfold kSpaceSize; destruct RBG as (_ & _ & R3); destruct SBR4 as (S1 & S2 & _); clear - S1 S2 R3 ERB HC; try acb; repeat split; [lia|lia|]; rewrite ERB in R3;
                Z.div_mod_to_equations; nia).
      all: replace (bv_unsigned sp + -160 + -64) with (bv_unsigned sp + -224) by lia. all: try eassumption.
      { clear - HI; try acb; lia. }
      { destruct MUA as [MUA']. unfold kUserMapSize, kFreeArrayOffset in *. change (au + class_size c * (n - nf)) with (rf_total c nf au).
        clear - AUR MUA' TOT TOTB CSZ; try acb. lia. } }
    clear OK1 VIS1. intros msF2 mo2 OK2 SBM2 HS2 P2.
    destruct P2 as (m2 & j44 & VIS2 & MU2 & WM2 & MI2 & ST2 & F160 & F96 & F64). cbv zeta in VIS2, F160, F96.
    rewrite ?unsigned_lit in VIS2, MU2, ST2, F160, F96, F64 by (first [clear - BND HI; lia | lia]).
    replace (bv_unsigned sp + -160 + -192) with (bv_unsigned sp + -352) in * by lia.   (* [comment removed for export] *)
    replace (bv_unsigned sp + -160 + -96) with (bv_unsigned sp + -256) in * by lia.
    replace (bv_unsigned sp + -160 - 464) with (bv_unsigned sp + -624) in * by lia.
    replace (bv_unsigned sp + -160 + -64) with (bv_unsigned sp + -224) in * by lia.
    fold rbeg in VIS2, F160, F96. fold csz in VIS2, F160. fold n in F64. change (au + csz * (n - nf)) with (rf_total c nf au) in *. rewrite MS256 in VIS2, F160.
    assert (BEGB : rbeg <= rbeg + mu /\ rbeg + mu + 262144 <= rbeg + 3758096384 /\ (exists bq, rbeg + mu = 4096 * bq)).
    { getAL CAR ARIR SBR4 RR RBG. destruct RBG as (_ & _ & R3). destruct MUA as [MUA']. unfold kUserMapSize in MUA'. clear - AUR R3 MUA'; try acb.
      split; [lia| split; [lia| exists ((rbeg + mu) / 4096); Z.div_mod_to_equations; lia]]. }
    destruct BEGB as (BEG1 & BEG2 & [bq BQ]).
    renv_at ENV1 MU2 WM2 ENV2. clear ENV1 ISB PMH GOT PSC DPM.
    assert (FAM1 : forall c', 1 <= c' <= 31 -> exists mc cs, rw_cells asegs m1 (CA + 80 * c' + 4) [C4 mc] /\ rw_cells asegs m1 (CA + 80 * c' + 8) [C8 cs]
                                           /\ (mc = wz (max_count c') /\ cs = wz (class_size c')))
      by (intros c' Hc'; destruct (FAMv c' Hc') as [A B]; eexists _, _; split; [exact A| split; [exact B| split; reflexivity]]).
    clear FAMv.
    assert (FAM2 := fam_transport CA _ m1 m2 _ FAM1 MU2 WM2 ltac:(hci; intros c' Hc'; cbn [disjoint_from]; clear - Hc' BND BNDL CAE HI; try acb; subst CA; repeat split; lia)).
    clear FAM1 FRP. unfold rinfo_cells in RI.
    (* [comment removed for export] *)
    eapply (munch_weaken _ (rf_W lo (bv_unsigned sp) P R FAB rbeg TH CA nf mfa mu mfa (mu + 262144))) in MU; [| unfold rf_W; rx_sub_fp_struct]. unfold rf_W in MU.
    replace (rbeg + (mu + 262144)) with (rbeg + mu + 262144) in MU by lia. replace (mu + 262144 - mu) with 262144 in MU by lia.
    transport_after_call asegs m1 m2 MU2 WM2. clear MU2 WM2.
    (* [comment removed for export] *)
    eapply (sr_ecall_MS L S Zr _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F 0x08598c fc None m2 msF2 mo2 Q OK2 VIS2 ecall_85b04).
    clear OK2 VIS2. intros msF3 OK3 VIS3 HS3.
    (* [comment removed for export] *)
    assert (NZ : page_round_up_Z (bv_unsigned (wz 262144)) = 262144) by (vm_compute; reflexivity).
    pose proof (same_but_materialized_trans _ _ _ SBM1 SBM2) as SBM.
    eapply (sr_mmap_commit_MS L S Zr _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ F 0x08598c fc None m2 false msF3 mo2 Q OK3 VIS3 eq_refl);
      rewrite ?NZ, ?(same_but_materialized_vmmaps _ _ SBM), ?(same_but_materialized_eager _ _ SBM); unfold wz; rewrite ?unsigned_lit by (first [clear - BEG2 BEG1 BNDL BND HI; lia | lia]).
    { apply wz_ne0. clear; lia. }
    { reflexivity. } { reflexivity. } { reflexivity. } { reflexivity. }
    { rewrite ATOP. clear - BEG1 BEG2 BND BNDL; try acb. lia. }
    { unfold page_size. rewrite BQ. clear. Z.div_mod_to_equations. lia. }
    { clear - BEG1 BND BNDL; try acb. lia. }
